#include <immintrin.h>
#include "exposed.hpp"
using U=std::uint64_t;using W=__uint128_t;
struct Wide4 { __m256i low,high; };
#define AVX __attribute__((target("avx2"),always_inline)) inline
static AVX Wide4 wide4(__m256i a,__m256i b){
 const __m256i mask=_mm256_set1_epi64x(0xffffffffULL),ah=_mm256_srli_epi64(a,32),bh=_mm256_srli_epi64(b,32);
 const __m256i low=_mm256_mul_epu32(a,b);
 const __m256i middle=_mm256_add_epi64(_mm256_mul_epu32(ah,b),_mm256_srli_epi64(low,32));
 const __m256i upper=_mm256_add_epi64(_mm256_mul_epu32(a,bh),_mm256_and_si256(middle,mask));
 const __m256i high=_mm256_add_epi64(_mm256_mul_epu32(ah,bh),_mm256_add_epi64(_mm256_srli_epi64(middle,32),_mm256_srli_epi64(upper,32)));
 return {_mm256_or_si256(_mm256_slli_epi64(upper,32),_mm256_and_si256(low,mask)),high};
}
static AVX __m256i low4(__m256i a,__m256i b){
 const __m256i cross=_mm256_add_epi64(_mm256_mul_epu32(_mm256_srli_epi64(a,32),b),_mm256_mul_epu32(a,_mm256_srli_epi64(b,32)));
 return _mm256_add_epi64(_mm256_mul_epu32(a,b),_mm256_slli_epi64(cross,32));
}
static AVX __m256i mont4(__m256i a,__m256i b,__m256i inv,__m256i n){
 const auto value=wide4(a,b);const auto correction=wide4(low4(value.low,inv),n);
 return _mm256_sub_epi64(_mm256_add_epi64(value.high,n),correction.high);
}
__attribute__((target("avx2"),noinline)) static void validate_vector(const std::array<U,4>&a,const std::array<U,4>&b,U inverse,U modulus,std::array<U,4>&out,std::array<U,4>&lo,std::array<U,4>&hi){
 auto av=_mm256_loadu_si256(reinterpret_cast<const __m256i*>(a.data())),bv=_mm256_loadu_si256(reinterpret_cast<const __m256i*>(b.data()));
 auto value=wide4(av,bv);auto result=mont4(av,bv,_mm256_set1_epi64x(inverse),_mm256_set1_epi64x(modulus));
 _mm256_storeu_si256(reinterpret_cast<__m256i*>(out.data()),result);_mm256_storeu_si256(reinterpret_cast<__m256i*>(lo.data()),value.low);_mm256_storeu_si256(reinterpret_cast<__m256i*>(hi.data()),value.high);
}
__attribute__((noinline)) static U scalar3(U n,U inverse,const std::array<U,4>&a,const std::array<U,4>&b,unsigned count,unsigned mode){
 const auto mul=[n,inverse](U x,U y){W t=W(x)*y;return U(t>>64)+n-U((W(U(t)*inverse)*n)>>64);};
 U x=a[0],y=a[1],z=a[2];for(unsigned i=0;i<count;++i){
  if(mode==0){x=mul(x,x);y=mul(y,y);z=mul(z,z);}else if(mode==1){x=mul(x,b[0]);y=mul(y,b[1]);z=mul(z,b[2]);}else{x=mul(x,x);y=mul(y,y);z=mul(z,z);if(i&1){x=mul(x,b[0]);y=mul(y,b[1]);z=mul(z,b[2]);}}
 }return x^y^z;
}
__attribute__((target("avx2"),noinline)) static U vector4(U n,U inverse,const std::array<U,4>&a,const std::array<U,4>&b,unsigned count,unsigned mode){
 const auto nv=_mm256_set1_epi64x(n),iv=_mm256_set1_epi64x(inverse),bv=_mm256_loadu_si256(reinterpret_cast<const __m256i*>(b.data()));
 auto x=_mm256_loadu_si256(reinterpret_cast<const __m256i*>(a.data()));for(unsigned i=0;i<count;++i){
  if(mode==0)x=mont4(x,x,iv,nv);else if(mode==1)x=mont4(x,bv,iv,nv);else{x=mont4(x,x,iv,nv);if(i&1)x=mont4(x,bv,iv,nv);}
 }std::array<U,4>out{};_mm256_storeu_si256(reinterpret_cast<__m256i*>(out.data()),x);return out[0]^out[1]^out[2];
}
int main(){if(!__builtin_cpu_supports("avx2")){std::puts("AVX2 unavailable");return 0;}std::mt19937_64 rng(412878);std::size_t checks=0;
 std::vector<U> ns{3,5,65537,4294967291ULL,4759123141ULL,(U(1)<<61)-1,(U(1)<<62)-3,(U(1)<<62)-1};for(unsigned i=0;i<80;++i)ns.push_back((rng()%((U(1)<<62)-3))|3);
 for(U n:ns){reinsirk::detail::MillerRabin64<true> c(n);for(unsigned iter=0;iter<256;++iter){std::array<U,4>a{},b{},out{},lo{},hi{};for(unsigned j=0;j<4;++j){a[j]=rng()%(2*n);b[j]=rng()%(2*n);}if(iter<4){a[0]=iter==0?0:iter==1?1:iter==2?n:2*n-1;b[0]=2*n-1;}
 validate_vector(a,b,c.reduction_inverse_,n,out,lo,hi);for(unsigned j=0;j<4;++j){W t=W(a[j])*b[j];if(lo[j]!=U(t)||hi[j]!=U(t>>64)||out[j]!=c.multiply(a[j],b[j])||out[j]>=2*n)std::abort();++checks;}}
 }
