#include SIRKIT_HEADER
using U=std::uint64_t;using W=__uint128_t;
static std::size_t checks=0,contexts=0,triples=0;
static U widths=0,shifts_seen=0;
static void need(bool v){++checks;if(!v)std::abort();}
static U mpow(U a,U e,U n){U x=1;while(e){if(e&1)x=W(x)*a%n;a=W(a)*a%n;e>>=1;}return x;}
